            // covA.z = Sigma[0][2]
            // covB.x = Sigma[1][1]
            // covB.y = Sigma[1][2]
            // covB.z = Sigma[2][2]
            
            covA = vec3(Sigma[0][0], Sigma[0][1], Sigma[0][2]);
            covB = vec3(Sigma[1][1], Sigma[1][2], Sigma[2][2]);
        #else
            // Fallback to static covariance
            getCovariance(covA, covB);
